def transform(grid):
    """
    Transform input grid to output grid by extracting distinctive marker sections.

    - Background values: border color (most common in header) and fill color (8)
    - Marker each row has distinctive border values (non-filler values at positions 0 or -1)
    - Extract marker values from marker sections at marker column positions
    - Output: distinctive marker sections vs unique marker values
    """
    grid = np.array(grid)

    # Get border color (most common in header)
    header = grid[0]
    unique_vals = np.unique(header)
    val_counts = dict(zip(unique_vals, np.bincount(header.astype(int))))
    border_color = max(val_counts, key=val_counts.get)

    # Fill color from row 2 middle pattern
    fill_color = 8  # From rows with "1, 8, 1,..." pattern

    bg = {border_color, fill_color}

    # Find marker columns (header values that differ from border)
    marker_cols = [c for c in range(grid.shape[1]) if grid[0, c] != border_color]

    # Find marker rows (rows with distinctive border values)
    mark_rows = []
    for r in range(grid.shape[0]):
        row = grid[r]
        if row[0] not in bg or row[-1] not in bg:
            mark_rows.append(r)

    # Group marker rows into sections (within distance 2 are same section)
    sections = []
