                curr = [mark_rows[i]]
        sections.append(curr)

    # Get all distinctive marker values
    all_values = set()
    for section in sections:
        for r in section:
            for c in marker_cols:
                val = grid[r, c]
                if val not in bg:
                    all_values.add(val)

    # Create output grid
    num_rows = len(sections)
    num_cols = len(all_values) if all_values else 1

